export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface SpellingWord {
  word: string;
  hint: string;
}

export enum GameState {
  MENU = 'MENU',
  LOADING = 'LOADING',
  PLAYING = 'PLAYING',
  VICTORY = 'VICTORY'
}

export interface LetterStatus {
  char: string;
  status: 'empty' | 'correct' | 'current';
}

// Uses Web Audio API to generate sound effects without external assets

class AudioService {
  private ctx: AudioContext | null = null;
  private gainNode: GainNode | null = null;

  constructor() {
    // AudioContext must be initialized after a user interaction
  }

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.gainNode = this.ctx.createGain();
      this.gainNode.connect(this.ctx.destination);
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  public playSuccess() {
    this.init();
    if (!this.ctx || !this.gainNode) return;

    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(500, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(1000, this.ctx.currentTime + 0.1);

    const gain = this.ctx.createGain();
    gain.connect(this.ctx.destination);
    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);

    osc.connect(gain);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.3);
  }

  public playError() {
    this.init();
    if (!this.ctx || !this.gainNode) return;

    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, this.ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(100, this.ctx.currentTime + 0.2);

    const gain = this.ctx.createGain();
    gain.connect(this.ctx.destination);
    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.2);

    osc.connect(gain);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.2);
  }

  public playVictory() {
    this.init();
    if (!this.ctx) return;

    const notes = [523.25, 659.25, 783.99, 1046.50]; // C Major Arpeggio
    let time = this.ctx.currentTime;

    notes.forEach((freq, i) => {
      const osc = this.ctx!.createOscillator();
      const gain = this.ctx!.createGain();

      osc.type = 'triangle';
      osc.frequency.value = freq;

      gain.gain.setValueAtTime(0.2, time);
      gain.gain.exponentialRampToValueAtTime(0.01, time + 0.5);

      osc.connect(gain);
      gain.connect(this.ctx!.destination);

      osc.start(time);
      osc.stop(time + 0.5);

      time += 0.1;
    });
  }

  public async playPCMData(base64Data: string) {
    this.init();
    if (!this.ctx || !base64Data) return;

    try {
      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      // Decode the raw audio data (assuming Gemini returns usable audio format or we use browser decode)
      // Gemini TTS actually returns raw audio often, or MP3/WAV in newer models.
      // The Gemini API response typically needs to be decoded by AudioContext.
      const audioBuffer = await this.ctx.decodeAudioData(bytes.buffer);

      const source = this.ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(this.ctx.destination);
      source.start(0);
    } catch (e) {
      console.error("Error playing PCM data", e);
    }
  }
}

export const audioService = new AudioService();

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, SpellingWord } from "../types";

// NOTE: process.env.API_KEY is injected by the environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateWordList = async (difficulty: Difficulty): Promise<SpellingWord[]> => {
  const prompt = `Generate 5 spelling words for kids with difficulty level: ${difficulty}. 
  Include a simple, kid-friendly hint for each word.
  EASY: 3-4 letters, simple objects.
  MEDIUM: 5-7 letters, common words.
  HARD: 8+ letters, complex words.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              hint: { type: Type.STRING },
            },
            required: ["word", "hint"],
          },
        },
      },
    });

    const jsonText = response.text || "[]";
    return JSON.parse(jsonText) as SpellingWord[];
  } catch (error) {
    console.error("Gemini Word Generation Error:", error);
    // Fallback in case of API error/limit
    return [
      { word: "CAT", hint: "A furry pet that meows" },
      { word: "DOG", hint: "A loyal pet that barks" },
      { word: "SUN", hint: "It shines in the sky" }
    ];
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // Gentle female voice
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio || null;
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    return null;
  }
};

import React from 'react';

interface VirtualKeyboardProps {
  onKeyPress: (char: string) => void;
  disabled: boolean;
}

const KEYS = [
  ['Q', 'W', 'E', 'R', 'T', 'Y', 'U', 'I', 'O', 'P'],
  ['A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L'],
  ['Z', 'X', 'C', 'V', 'B', 'N', 'M']
];

const VirtualKeyboard: React.FC<VirtualKeyboardProps> = ({ onKeyPress, disabled }) => {
  return (
    <div className="w-full max-w-3xl mx-auto p-4 select-none">
      {KEYS.map((row, rowIndex) => (
        <div key={rowIndex} className="flex justify-center gap-2 mb-2">
          {row.map((char) => (
            <button
              key={char}
              onClick={() => !disabled && onKeyPress(char)}
              disabled={disabled}
              className={`
                relative
                h-12 w-8 sm:h-14 sm:w-12 md:h-16 md:w-14 lg:w-16
                text-lg sm:text-xl font-bold rounded-lg
                transition-all duration-100
                shadow-[0_4px_0_rgb(0,0,0,0.2)]
                active:shadow-none active:translate-y-[4px]
                ${disabled 
                  ? 'bg-gray-200 text-gray-400 cursor-not-allowed shadow-none translate-y-[2px]' 
                  : 'bg-white text-indigo-600 hover:bg-indigo-50 border-2 border-indigo-100'}
              `}
            >
              {char}
            </button>
          ))}
        </div>
      ))}
    </div>
  );
};

export default VirtualKeyboard;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger';
  size?: 'sm' | 'md' | 'lg';
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}) => {
  const baseStyles = "font-bold rounded-2xl transition-all duration-150 transform active:scale-95 shadow-[0_6px_0_rgba(0,0,0,0.2)] active:shadow-none active:translate-y-[6px]";

  const variants = {
    primary: "bg-yellow-400 text-yellow-900 hover:bg-yellow-300 border-2 border-yellow-500",
    secondary: "bg-blue-500 text-white hover:bg-blue-400 border-2 border-blue-600",
    danger: "bg-red-500 text-white hover:bg-red-400 border-2 border-red-600"
  };

  const sizes = {
    sm: "px-4 py-2 text-sm",
    md: "px-8 py-4 text-xl",
    lg: "px-12 py-6 text-2xl"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

import React from 'react';

interface WordDisplayProps {
  targetWord: string;
  currentIndex: number;
  isShake: boolean;
}

const WordDisplay: React.FC<WordDisplayProps> = ({ targetWord, currentIndex, isShake }) => {
  return (
    <div className={`flex flex-wrap justify-center gap-2 sm:gap-4 my-8 sm:my-12 px-2 ${isShake ? 'shake' : ''}`}>
      {targetWord.split('').map((char, index) => {
        const isCompleted = index < currentIndex;
        const isCurrent = index === currentIndex;

        return (
          <div
            key={index}
            className={`
              w-12 h-16 sm:w-16 sm:h-20 md:w-20 md:h-24
              flex items-center justify-center
              text-3xl sm:text-5xl font-black rounded-xl border-b-8
              transition-all duration-300
              ${isCompleted 
                ? 'bg-green-400 border-green-600 text-white transform -translate-y-1' 
                : isCurrent
                  ? 'bg-white border-blue-400 text-blue-900 animate-pulse border-2'
                  : 'bg-white/50 border-slate-300 text-transparent border-2 border-dashed'
              }
            `}
          >
            {isCompleted ? char : ''}
          </div>
        );
      })}
    </div>
  );
};

export default WordDisplay;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { generateWordList, generateSpeech } from './services/geminiService';
import { audioService } from './services/audioService';
import VirtualKeyboard from './components/VirtualKeyboard';
import WordDisplay from './components/WordDisplay';
import Button from './components/Button';
import { Difficulty, GameState, SpellingWord } from './types';

// Icons
const VolumeIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-8 h-8">
    <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" />
  </svg>
);

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [wordList, setWordList] = useState<SpellingWord[]>([]);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  const [spelledIndex, setSpelledIndex] = useState(0);
  const [shake, setShake] = useState(false);
  const [loading, setLoading] = useState(false);

  // Cache for audio data to avoid re-fetching
  const audioCache = useRef<Map<string, string>>(new Map());

  const currentWordData = wordList[currentWordIndex];
  const targetWord = currentWordData?.word.toUpperCase() || "";

  // Helper to play the word sound
  const playWordAudio = useCallback(async (word: string) => {
    if (!word) return;

    // Check cache first
    if (audioCache.current.has(word)) {
      await audioService.playPCMData(audioCache.current.get(word)!);
      return;
    }

    // Fetch if not cached
    const audioData = await generateSpeech(`Spell the word: ${word}`);
    if (audioData) {
      audioCache.current.set(word, audioData);
      await audioService.playPCMData(audioData);
    }
  }, []);

  // Initialize Game
  const startGame = async (selectedDifficulty: Difficulty) => {
    setDifficulty(selectedDifficulty);
    setGameState(GameState.LOADING);
    setLoading(true);

    try {
      const words = await generateWordList(selectedDifficulty);
      setWordList(words);
      setCurrentWordIndex(0);
      setSpelledIndex(0);
      setGameState(GameState.PLAYING);

      // Pre-fetch audio for the first word
      if (words.length > 0) {
        // Give a slight delay for UI transition
        setTimeout(() => {
          playWordAudio(words[0].word);
        }, 500);
      }
    } catch (e) {
      console.error("Failed to start game", e);
      setGameState(GameState.MENU);
    } finally {
      setLoading(false);
    }
  };

  // Handle Input
  const handleInput = useCallback((char: string) => {
    if (gameState !== GameState.PLAYING) return;

    const correctChar = targetWord[spelledIndex];

    if (char.toUpperCase() === correctChar) {
      // Correct
      audioService.playSuccess();
      const nextIndex = spelledIndex + 1;
      setSpelledIndex(nextIndex);

      if (nextIndex === targetWord.length) {
        // Word Completed
        setTimeout(() => {
          audioService.playVictory();
          handleNextWord();
        }, 500);
      }
    } else {
      // Wrong
      audioService.playError();
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  }, [gameState, targetWord, spelledIndex, playWordAudio]);

  const handleNextWord = () => {
    if (currentWordIndex + 1 < wordList.length) {
      setCurrentWordIndex(prev => prev + 1);
      setSpelledIndex(0);
      // Play next word
      setTimeout(() => {
        playWordAudio(wordList[currentWordIndex + 1].word);
      }, 1000);
    } else {
      setGameState(GameState.VICTORY);
    }
  };

  // Keyboard Event Listener
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const char = e.key.toUpperCase();
      if (/^[A-Z]$/.test(char)) {
        handleInput(char);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleInput]);


  // Renders
  if (gameState === GameState.MENU) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]">
        <div className="max-w-2xl w-full text-center space-y-8 bg-white/90 backdrop-blur-sm p-12 rounded-3xl shadow-2xl border-4 border-white">
          <h1 className="text-6xl font-black text-indigo-600 tracking-tight animate-float">
            SpellBound <span className="text-yellow-500">Kids</span>
          </h1>
          <p className="text-2xl text-slate-600 font-medium">Choose your challenge level!</p>

          <div className="flex flex-col sm:flex-row gap-4 justify-center pt-8">
            <Button onClick={() => startGame(Difficulty.EASY)} variant="primary" size="lg">
              Easy 🌟
            </Button>
            <Button onClick={() => startGame(Difficulty.MEDIUM)} variant="secondary" size="lg">
              Medium 🚀
            </Button>
            <Button onClick={() => startGame(Difficulty.HARD)} variant="danger" size="lg">
              Hard 🦁
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (gameState === GameState.LOADING) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center space-y-6">
        <div className="w-24 h-24 border-8 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
        <h2 className="text-3xl font-bold text-blue-600 animate-pulse">Making Magic Words...</h2>
      </div>
    );
  }

  if (gameState === GameState.VICTORY) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 text-center bg-yellow-100">
        <h1 className="text-6xl md:text-8xl font-black text-yellow-500 mb-8 drop-shadow-lg animate-bounce">
          CONGRATULATIONS!
        </h1>
        <p className="text-3xl text-slate-700 mb-12">You are a Spelling Master! 🏆</p>
        <Button onClick={() => setGameState(GameState.MENU)} size="lg" variant="secondary">
          Play Again
        </Button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col max-w-5xl mx-auto p-4">
      {/* Header */}
      <header className="flex justify-between items-center py-4 px-2">
        <button 
          onClick={() => setGameState(GameState.MENU)}
          className="text-slate-500 font-bold hover:text-slate-800 transition-colors"
        >
          ← Quit
        </button>
        <div className="text-2xl font-bold text-slate-700 bg-white px-6 py-2 rounded-full shadow-sm">
          Word {currentWordIndex + 1} / {wordList.length}
        </div>
      </header>

      {/* Main Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center -mt-8">

        {/* Helper/Hint Section */}
        <div className="text-center mb-6 space-y-4">
           <button 
            onClick={() => playWordAudio(targetWord)}
            className="inline-flex items-center gap-2 bg-indigo-100 hover:bg-indigo-200 text-indigo-700 px-8 py-4 rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-md"
          >
            <VolumeIcon />
            <span className="text-xl font-bold">Listen Again</span>
          </button>

          <div className="bg-white/60 px-6 py-2 rounded-xl text-slate-600 font-medium">
            Hint: {currentWordData?.hint}
          </div>
        </div>

        {/* The Word Grid */}
        <WordDisplay 
          targetWord={targetWord} 
          currentIndex={spelledIndex} 
          isShake={shake}
        />

      </main>

      {/* Keyboard */}
      <footer className="pb-4">
        <VirtualKeyboard 
          onKeyPress={handleInput} 
          disabled={false}
        />
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, SpellingWord } from "../types";

// NOTE: process.env.API_KEY is injected by the environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateWordList = async (difficulty: Difficulty): Promise<SpellingWord[]> => {
  const prompt = `Generate 5 spelling words for kids with difficulty level: ${difficulty}. 
  Include a simple, kid-friendly hint for each word.
  EASY: 3-4 letters, simple objects.
  MEDIUM: 5-7 letters, common words.
  HARD: 8+ letters, complex words.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              hint: { type: Type.STRING },
            },
            required: ["word", "hint"],
          },
        },
      },
    });

    let jsonText = response.text || "[]";
    // Sanitize response: remove Markdown code blocks if present
    jsonText = jsonText.replace(/```json\s*/g, "").replace(/```/g, "").trim();

    return JSON.parse(jsonText) as SpellingWord[];
  } catch (error) {
    console.error("Gemini Word Generation Error:", error);
    // Fallback in case of API error/limit
    return [
      { word: "CAT", hint: "A furry pet that meows" },
      { word: "DOG", hint: "A loyal pet that barks" },
      { word: "SUN", hint: "It shines in the sky" },
      { word: "BOOK", hint: "Something you read" },
      { word: "TREE", hint: "It has leaves and grows tall" }
    ];
  }
};

