export const generateWordList = async (difficulty: Difficulty, letter: string | null = null): Promise<SpellingWord[]> => {
  const difficultyData = RAW_DATA[difficulty];
  let pool: string[] = [];

  if (letter && letter !== 'ALL') {
    // Get words for specific letter
    pool = difficultyData[letter] || [];
  } else {
    // Get words from all letters
    Object.values(difficultyData).forEach(words => {
      pool = [...pool, ...words];
    });
  }

  // Shuffle array using Fisher-Yates algorithm
  const shuffled = [...pool];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  // Return top 5 words, expanded into objects
  return shuffled.slice(0, 5).map(expand);
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'outline' | 'selected';
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}) => {
  const baseStyles = "font-bold rounded-2xl transition-all duration-150 transform active:scale-95 shadow-[0_4px_0_rgba(0,0,0,0.2)] active:shadow-none active:translate-y-[4px]";

  const variants = {
    primary: "bg-yellow-400 text-yellow-900 hover:bg-yellow-300 border-2 border-yellow-500",
    secondary: "bg-blue-500 text-white hover:bg-blue-400 border-2 border-blue-600",
    danger: "bg-red-500 text-white hover:bg-red-400 border-2 border-red-600",
    outline: "bg-white text-slate-600 hover:bg-slate-50 border-2 border-slate-300 shadow-[0_4px_0_rgba(203,213,225,1)]",
    selected: "bg-indigo-600 text-white border-2 border-indigo-800 shadow-[0_4px_0_rgba(55,48,163,1)] ring-2 ring-indigo-300 ring-offset-2"
  };

  const sizes = {
    sm: "px-3 py-1 text-sm",
    md: "px-6 py-3 text-lg",
    lg: "px-8 py-4 text-xl",
    xl: "w-12 h-12 flex items-center justify-center text-xl p-0" // Square button for grid
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

