// --- Custom Word Management ---

export const getCustomWords = (): CustomWord[] => {
  try {
    const stored = localStorage.getItem(CUSTOM_WORDS_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error("Failed to load custom words", e);
    return [];
  }
};

export const addCustomWord = (word: string, hint: string, difficulty: Difficulty) => {
  const words = getCustomWords();
  const newWord: CustomWord = {
    id: Date.now().toString(),
    word: word.toUpperCase().trim(),
    hint: hint.trim(),
    difficulty
  };
  localStorage.setItem(CUSTOM_WORDS_KEY, JSON.stringify([...words, newWord]));
  return newWord;
};

export const deleteCustomWord = (id: string) => {
  const words = getCustomWords();
  const filtered = words.filter(w => w.id !== id);
  localStorage.setItem(CUSTOM_WORDS_KEY, JSON.stringify(filtered));
};

// --- Generation Logic ---

export const generateWordList = async (difficulty: Difficulty, letter: string | null = null): Promise<SpellingWord[]> => {
  const difficultyData = RAW_DATA[difficulty];
  let pool: SpellingWord[] = [];

  // 1. Get Built-in Words
  if (letter && letter !== 'ALL') {
    // Get words for specific letter
    const rawStrings = difficultyData[letter] || [];
    pool = rawStrings.map(expand);
  } else {
    // Get words from all letters
    Object.values(difficultyData).forEach(rawStrings => {
      pool = [...pool, ...rawStrings.map(expand)];
    });
  }

  // 2. Get Custom Words
  const customWords = getCustomWords().filter(w => {
    // Filter by difficulty
    if (w.difficulty !== difficulty) return false;
    // Filter by letter
    if (letter && letter !== 'ALL' && w.word[0] !== letter) return false;
    return true;
  });

  // 3. Combine
  const fullPool = [...pool, ...customWords];

  // 4. Shuffle array using Fisher-Yates algorithm
  const shuffled = [...fullPool];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  // 5. Return top 5 words
  return shuffled.slice(0, 5);
};

import React, { useState, useEffect } from 'react';
import { Difficulty, CustomWord } from '../types';
import { getCustomWords, addCustomWord, deleteCustomWord } from '../services/wordService';
import Button from './Button';

interface AdminPanelProps {
  onBack: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onBack }) => {
  const [words, setWords] = useState<CustomWord[]>([]);

  // Form State
  const [newWord, setNewWord] = useState('');
  const [newHint, setNewHint] = useState('');
  const [newDifficulty, setNewDifficulty] = useState<Difficulty>(Difficulty.EASY);

  useEffect(() => {
    loadWords();
  }, []);

  const loadWords = () => {
    setWords(getCustomWords());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWord || !newHint) return;

    addCustomWord(newWord, newHint, newDifficulty);
    setNewWord('');
    setNewHint('');
    loadWords();
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this word?')) {
      deleteCustomWord(id);
      loadWords();
    }
  };

  return (
    <div className="min-h-screen p-4 md:p-8 bg-sky-50 dark:bg-slate-900 transition-colors">
      <div className="max-w-4xl mx-auto space-y-8">
        <div className="flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-800 dark:text-white">Instructor Panel</h2>
          <Button onClick={onBack} variant="outline" size="sm">
            ← Back to Menu
          </Button>
        </div>

        {/* Add New Word Form */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700">
          <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-4">Add New Word</h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <input
              type="text"
              placeholder="Word (e.g., ZEBRA)"
              value={newWord}
              onChange={(e) => setNewWord(e.target.value.toUpperCase())}
              className="p-3 border rounded-xl dark:bg-slate-900 dark:text-white dark:border-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none"
              required
            />
            <input
              type="text"
              placeholder="Hint (e.g., Striped horse)"
              value={newHint}
              onChange={(e) => setNewHint(e.target.value)}
              className="p-3 border rounded-xl dark:bg-slate-900 dark:text-white dark:border-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none"
              required
            />
            <select
              value={newDifficulty}
              onChange={(e) => setNewDifficulty(e.target.value as Difficulty)}
              className="p-3 border rounded-xl dark:bg-slate-900 dark:text-white dark:border-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none"
            >
              <option value={Difficulty.EASY}>Easy</option>
              <option value={Difficulty.MEDIUM}>Medium</option>
              <option value={Difficulty.HARD}>Hard</option>
            </select>
            <Button type="submit" variant="primary">Add Word</Button>
          </form>
        </div>

        {/* Word List */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700">
          <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-4">Custom Words Database</h3>
          {words.length === 0 ? (
            <p className="text-slate-500 italic text-center py-8">No custom words added yet.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="text-slate-500 border-b dark:border-slate-600">
                    <th className="pb-2">Word</th>
                    <th className="pb-2">Hint</th>
                    <th className="pb-2">Level</th>
                    <th className="pb-2 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="text-slate-700 dark:text-slate-300">
                  {words.map((w) => (
                    <tr key={w.id} className="border-b last:border-0 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700/50">
                      <td className="py-3 font-bold">{w.word}</td>
                      <td className="py-3">{w.hint}</td>
                      <td className="py-3">
                        <span className={`text-xs font-bold px-2 py-1 rounded-full ${
                          w.difficulty === Difficulty.EASY ? 'bg-green-100 text-green-700' :
                          w.difficulty === Difficulty.MEDIUM ? 'bg-blue-100 text-blue-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {w.difficulty}
                        </span>
                      </td>
                      <td className="py-3 text-right">
                        <button 
                          onClick={() => handleDelete(w.id)}
                          className="text-red-500 hover:text-red-700 font-bold text-sm bg-red-50 dark:bg-red-900/20 px-3 py-1 rounded-lg transition-colors"
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;

