              <button
                onClick={() => updateTheme('light')}
                className={`flex-1 p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all ${
                  settings.theme === 'light' 
                    ? 'border-indigo-500 bg-indigo-50 text-indigo-700 shadow-md ring-2 ring-indigo-200' 
                    : 'border-slate-200 text-slate-500 hover:bg-slate-50'
                }`}
              >
                <span className="text-2xl">☀️</span>
                <span className="font-bold">Light Mode</span>
              </button>
              <button
                onClick={() => updateTheme('dark')}
                className={`flex-1 p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all ${
                  settings.theme === 'dark' 
                    ? 'border-indigo-500 bg-slate-900 text-indigo-400 shadow-md ring-2 ring-indigo-900' 
                    : 'border-slate-200 text-slate-500 hover:bg-slate-50'
                }`}
              >
                <span className="text-2xl">🌙</span>
                <span className="font-bold">Dark Mode</span>
              </button>
            </div>
          </div>

          {/* Font Selection */}
          <div className="space-y-3">
            <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Lettering Style</h3>
            <div className="grid grid-cols-2 gap-3">
              <button
                onClick={() => updateFont('sans')}
                className={`p-3 rounded-xl border-2 font-sans transition-all ${settings.font === 'sans' ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300' : 'border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-400'}`}
              >
                Simple Sans
              </button>
              <button
                onClick={() => updateFont('serif')}
                className={`p-3 rounded-xl border-2 font-serif transition-all ${settings.font === 'serif' ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300' : 'border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-400'}`}
              >
                Classic Serif
              </button>
              <button
                onClick={() => updateFont('mono')}
                className={`p-3 rounded-xl border-2 font-mono transition-all ${settings.font === 'mono' ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300' : 'border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-400'}`}
              >
                Code Mono
              </button>
              <button
                onClick={() => updateFont('comic')}
                className={`p-3 rounded-xl border-2 font-comic transition-all ${settings.font === 'comic' ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300' : 'border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-400'}`}
              >
                Fun Comic
              </button>
            </div>
          </div>

          <div className="pt-4">
            <Button onClick={onBack} variant="secondary" className="w-full">
              Done
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsPanel;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'outline' | 'selected';
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}) => {
  const baseStyles = "font-bold rounded-2xl transition-all duration-150 transform active:scale-95 shadow-[0_4px_0_rgba(0,0,0,0.2)] dark:shadow-[0_4px_0_rgba(0,0,0,0.4)] active:shadow-none active:translate-y-[4px]";

  const variants = {
    primary: "bg-yellow-400 text-yellow-900 hover:bg-yellow-300 border-2 border-yellow-500 dark:border-yellow-600",
    secondary: "bg-blue-500 text-white hover:bg-blue-400 border-2 border-blue-600 dark:border-blue-700",
    danger: "bg-red-500 text-white hover:bg-red-400 border-2 border-red-600 dark:border-red-700",
    outline: "bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 border-2 border-slate-300 dark:border-slate-600 shadow-[0_4px_0_rgba(203,213,225,1)] dark:shadow-[0_4px_0_rgba(71,85,105,1)]",
    selected: "bg-indigo-600 text-white border-2 border-indigo-800 shadow-[0_4px_0_rgba(55,48,163,1)] ring-2 ring-indigo-300 dark:ring-indigo-700 ring-offset-2 dark:ring-offset-slate-900"
  };

  const sizes = {
    sm: "px-3 py-1 text-sm",
    md: "px-6 py-3 text-lg",
    lg: "px-8 py-4 text-xl",
    xl: "w-12 h-12 flex items-center justify-center text-xl p-0" // Square button for grid
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

