import React, { useState, useEffect, useCallback } from 'react';
import { generateWordList } from './services/wordService';
import { audioService } from './services/audioService';
import VirtualKeyboard from './components/VirtualKeyboard';
import WordDisplay from './components/WordDisplay';
import Button from './components/Button';
import AdminPanel from './components/AdminPanel';
import SettingsPanel from './components/SettingsPanel';
import { Difficulty, GameState, SpellingWord, AppSettings } from './types';

// Icons
const VolumeIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-8 h-8">
    <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" />
  </svg>
);

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [selectedLetter, setSelectedLetter] = useState<string>('ALL');
  const [wordList, setWordList] = useState<SpellingWord[]>([]);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  const [spelledIndex, setSpelledIndex] = useState(0);
  const [shake, setShake] = useState(false);
  const [loading, setLoading] = useState(false);

  // Score State
  const [score, setScore] = useState(0);

  // Settings State
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('spellbound_settings');
    return saved ? JSON.parse(saved) : { theme: 'light', font: 'sans' };
  });

  const currentWordData = wordList[currentWordIndex];
  const targetWord = currentWordData?.word.toUpperCase() || "";

  // Apply Theme & Font
  useEffect(() => {
    // Save settings
    localStorage.setItem('spellbound_settings', JSON.stringify(settings));

    // Apply Dark Mode
    if (settings.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Apply Font
    document.body.className = `bg-sky-100 dark:bg-slate-900 text-slate-800 dark:text-slate-100 transition-colors duration-300 selection:bg-yellow-200 font-${settings.font}`;
  }, [settings]);

  // Use browser native SpeechSynthesis
  const playWordAudio = useCallback((word: string) => {
    if (!word) return;

    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.rate = 0.8;
    utterance.pitch = 1.1;

    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => 
      v.name.includes('Google US English') || 
      (v.lang.startsWith('en') && v.name.includes('Female'))
    ) || voices.find(v => v.lang.startsWith('en'));

    if (preferredVoice) utterance.voice = preferredVoice;
    window.speechSynthesis.speak(utterance);
  }, []);

  const getPointsPerWord = (diff: Difficulty) => {
    switch (diff) {
      case Difficulty.EASY: return 10;
      case Difficulty.MEDIUM: return 20;
      case Difficulty.HARD: return 30;
    }
  };

  const startGame = async () => {
    setGameState(GameState.LOADING);
    setLoading(true);
    setScore(0); // Reset score

    try {
      const words = await generateWordList(difficulty, selectedLetter);
      setWordList(words);
      setCurrentWordIndex(0);
      setSpelledIndex(0);
      setGameState(GameState.PLAYING);

      if (words.length > 0) {
        setTimeout(() => {
          playWordAudio(words[0].word);
        }, 800);
      }
    } catch (e) {
      console.error("Failed to start game", e);
      setGameState(GameState.MENU);
    } finally {
      setLoading(false);
    }
  };

  const handleInput = useCallback((char: string) => {
    if (gameState !== GameState.PLAYING) return;

    const correctChar = targetWord[spelledIndex];

    if (char.toUpperCase() === correctChar) {
      // Correct Letter
      audioService.playSuccess();
      const nextIndex = spelledIndex + 1;
      setSpelledIndex(nextIndex);

      if (nextIndex === targetWord.length) {
        // Word Completed
        const points = getPointsPerWord(difficulty);
        setScore(prev => prev + points);

        setTimeout(() => {
          audioService.playVictory();
          handleNextWord();
        }, 500);
      }
    } else {
      // Wrong Letter
      audioService.playError();
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  }, [gameState, targetWord, spelledIndex, difficulty, playWordAudio]);

  const handleNextWord = () => {
    if (currentWordIndex + 1 < wordList.length) {
      setCurrentWordIndex(prev => prev + 1);
      setSpelledIndex(0);
      setTimeout(() => {
        playWordAudio(wordList[currentWordIndex + 1].word);
      }, 1000);
    } else {
      setGameState(GameState.VICTORY);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const char = e.key.toUpperCase();
      if (/^[A-Z]$/.test(char)) {
        handleInput(char);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleInput]);


  // --- Render Views ---

  if (gameState === GameState.ADMIN) {
    return <AdminPanel onBack={() => setGameState(GameState.MENU)} />;
  }

  if (gameState === GameState.MENU) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed">

        {/* Settings Overlay */}
        {gameState === GameState.SETTINGS && (
           <div className="fixed inset-0 z-50">
             {/* This will be handled by simple state toggle instead of enum for overlay behavior or just replace view */}
           </div>
        )}

        <div className="max-w-4xl w-full text-center space-y-6 bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm p-8 md:p-12 rounded-3xl shadow-2xl border-4 border-white dark:border-slate-700 my-8 transition-colors">
          <div className="flex justify-end gap-2 absolute top-6 right-6">
             <button 
              onClick={() => setGameState(GameState.SETTINGS)}
              className="p-2 text-slate-400 hover:text-indigo-500 transition-colors"
              title="Settings"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
            </button>
          </div>

          <h1 className="text-5xl md:text-6xl font-black text-indigo-600 dark:text-indigo-400 tracking-tight animate-float mb-8">
            SpellBound <span className="text-yellow-500">Kids</span>
          </h1>

          <div className="space-y-8">
            {/* Difficulty Section */}
            <div className="space-y-3">
              <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">1. Select Level</h3>
              <div className="flex flex-wrap gap-4 justify-center">
                <Button 
                  onClick={() => setDifficulty(Difficulty.EASY)} 
                  variant={difficulty === Difficulty.EASY ? 'selected' : 'outline'}
                >
                  Easy 🌟
                </Button>
                <Button 
                  onClick={() => setDifficulty(Difficulty.MEDIUM)} 
                  variant={difficulty === Difficulty.MEDIUM ? 'selected' : 'outline'}
                >
                  Medium 🚀
                </Button>
                <Button 
                  onClick={() => setDifficulty(Difficulty.HARD)} 
                  variant={difficulty === Difficulty.HARD ? 'selected' : 'outline'}
                >
                  Hard 🦁
                </Button>
              </div>
            </div>

            {/* Alphabet Section */}
            <div className="space-y-3">
              <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">2. Select Letter</h3>
              <div className="flex flex-wrap justify-center gap-2 max-w-2xl mx-auto">
                <Button 
                  onClick={() => setSelectedLetter('ALL')}
                  variant={selectedLetter === 'ALL' ? 'selected' : 'outline'}
                  className="w-full sm:w-auto px-8"
                >
                  All Letters
                </Button>
                <div className="w-full"></div>
                {ALPHABET.map(letter => (
                  <Button
                    key={letter}
                    onClick={() => setSelectedLetter(letter)}
                    variant={selectedLetter === letter ? 'selected' : 'outline'}
                    size="xl"
                  >
                    {letter}
                  </Button>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="pt-8 flex flex-col md:flex-row gap-4 justify-center items-center">
              <Button onClick={() => setGameState(GameState.ADMIN)} variant="secondary" className="w-full md:w-auto">
                Instructor Panel 👨‍🏫
              </Button>
              <Button onClick={startGame} variant="primary" size="lg" className="w-full md:w-auto min-w-[200px] animate-pulse">
                START GAME ▶
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (gameState === GameState.SETTINGS) {
    return (
      <SettingsPanel 
        settings={settings} 
        onUpdate={setSettings} 
        onBack={() => setGameState(GameState.MENU)} 
      />
    );
  }

  if (gameState === GameState.LOADING) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center space-y-6 bg-sky-100 dark:bg-slate-900">
        <div className="w-24 h-24 border-8 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
        <h2 className="text-3xl font-bold text-blue-600 animate-pulse">Preparing Words...</h2>
      </div>
    );
  }

  if (gameState === GameState.VICTORY) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 text-center bg-yellow-100 dark:bg-slate-900 transition-colors">
        <h1 className="text-6xl md:text-8xl font-black text-yellow-500 mb-8 drop-shadow-lg animate-bounce">
          CONGRATULATIONS!
        </h1>
        <p className="text-3xl text-slate-700 dark:text-slate-200 mb-8">You are a Spelling Master! 🏆</p>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl mb-12 border-4 border-yellow-200 dark:border-slate-700">
          <p className="text-slate-500 dark:text-slate-400 uppercase tracking-widest font-bold mb-2">Final Score</p>
          <p className="text-6xl font-black text-indigo-600 dark:text-indigo-400">{score}</p>
        </div>

        <Button onClick={() => setGameState(GameState.MENU)} size="lg" variant="secondary">
          Play Again
        </Button>
      </div>
    );
  }

  // PLAYING STATE
  return (
    <div className="min-h-screen flex flex-col max-w-5xl mx-auto p-4">
      {/* Header */}
      <header className="flex justify-between items-center py-4 px-2">
        <button 
          onClick={() => setGameState(GameState.MENU)}
          className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-800 dark:hover:text-white transition-colors"
        >
          ← Quit
        </button>

        {/* Score Display */}
        <div className="flex gap-4">
            <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Score: <span className="text-indigo-600 dark:text-indigo-400">{score}</span>
          </div>
          <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Word {currentWordIndex + 1} / {wordList.length}
          </div>
        </div>
      </header>

      {/* Main Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center -mt-8">

        {/* Helper/Hint Section */}
        <div className="text-center mb-6 space-y-4">
           <button 
            onClick={() => playWordAudio(targetWord)}
            className="inline-flex items-center gap-2 bg-indigo-100 dark:bg-slate-800 hover:bg-indigo-200 dark:hover:bg-slate-700 text-indigo-700 dark:text-indigo-300 px-8 py-4 rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-md border-2 border-transparent dark:border-slate-600"
          >
            <VolumeIcon />
            <span className="text-xl font-bold">Listen Again</span>
          </button>

          <div className="bg-white/60 dark:bg-slate-800/60 px-6 py-2 rounded-xl text-slate-600 dark:text-slate-300 font-medium">
            Hint: {currentWordData?.hint}
          </div>
        </div>

        {/* The Word Grid */}
        <WordDisplay 
          targetWord={targetWord} 
          currentIndex={spelledIndex} 
          isShake={shake}
        />

      </main>

      {/* Keyboard */}
      <footer className="pb-4">
        <VirtualKeyboard 
          onKeyPress={handleInput} 
          disabled={false}
        />
      </footer>
    </div>
  );
};

export default App;

