        </h1>
        <p className="text-3xl text-slate-700 dark:text-slate-200 mb-8">You are a Spelling Master! 🏆</p>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl mb-12 border-4 border-yellow-200 dark:border-slate-700">
          <p className="text-slate-500 dark:text-slate-400 uppercase tracking-widest font-bold mb-2">Final Score</p>
          <p className="text-6xl font-black text-indigo-600 dark:text-indigo-400">{score}</p>
        </div>

        <Button onClick={() => setGameState(GameState.MENU)} size="lg" variant="secondary">
          Play Again
        </Button>
      </div>
    );
  }

  // PLAYING STATE
  return (
    <div className="min-h-screen flex flex-col max-w-5xl mx-auto p-4">
      {/* Header */}
      <header className="flex justify-between items-center py-4 px-2">
        <button 
          onClick={() => setGameState(GameState.MENU)}
          className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-800 dark:hover:text-white transition-colors"
        >
          ← Quit
        </button>

        {/* Score Display */}
        <div className="flex gap-4">
            <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Score: <span className="text-indigo-600 dark:text-indigo-400">{score}</span>
          </div>
          <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Word {currentWordIndex + 1} / {wordList.length}
          </div>
        </div>
      </header>

      {/* Main Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center -mt-8">

        {/* Helper/Hint Section */}
        <div className="text-center mb-6 space-y-4">
           <button 
            onClick={() => playWordAudio(targetWord)}
            className="inline-flex items-center gap-2 bg-indigo-100 dark:bg-slate-800 hover:bg-indigo-200 dark:hover:bg-slate-700 text-indigo-700 dark:text-indigo-300 px-8 py-4 rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-md border-2 border-transparent dark:border-slate-600"
          >
            <VolumeIcon />
            <span className="text-xl font-bold">Listen Again</span>
          </button>

          <div className="bg-white/60 dark:bg-slate-800/60 px-6 py-2 rounded-xl text-slate-600 dark:text-slate-300 font-medium">
            Hint: {currentWordData?.hint}
          </div>
        </div>

        {/* The Word Grid */}
        <WordDisplay 
          targetWord={targetWord} 
          currentIndex={spelledIndex} 
          isShake={shake}
        />

      </main>

      {/* Keyboard */}
      <footer className="pb-4">
        <VirtualKeyboard 
          onKeyPress={handleInput} 
          disabled={false}
        />
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Difficulty, CustomWord } from '../types';
import { getCustomWords, addCustomWord, deleteCustomWord } from '../services/wordService';
import Button from './Button';

interface AdminPanelProps {
  onBack: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onBack }) => {
  const [words, setWords] = useState<CustomWord[]>([]);

  // Form State
  const [newWord, setNewWord] = useState('');
  const [newHint, setNewHint] = useState('');
  const [newDifficulty, setNewDifficulty] = useState<Difficulty>(Difficulty.EASY);

  useEffect(() => {
    loadWords();
  }, []);

  const loadWords = () => {
    setWords(getCustomWords());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWord || !newHint) return;

    if (words.length >= 10) {
      alert("You can only set up to 10 words at a time. Please delete some completed tasks/words before adding new ones.");
      return;
    }

    addCustomWord(newWord, newHint, newDifficulty);
    setNewWord('');
    setNewHint('');
    loadWords();
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this word?')) {
      deleteCustomWord(id);
      loadWords();
    }
  };

  return (
    <div className="min-h-screen p-4 md:p-8 bg-sky-50 dark:bg-slate-900 transition-colors">
      <div className="max-w-4xl mx-auto space-y-8">
        <div className="flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-800 dark:text-white">Instructor Panel</h2>
          <Button onClick={onBack} variant="outline" size="sm">
            ← Back to Menu
          </Button>
        </div>

        {/* Add New Word Form */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200">Add New Word</h3>
            <span className={`text-sm font-bold px-3 py-1 rounded-full ${words.length >= 10 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
              {words.length}/10 Words
            </span>
          </div>

          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <input
              type="text"
              placeholder="Word (e.g., ZEBRA)"
              value={newWord}
              onChange={(e) => setNewWord(e.target.value.toUpperCase())}
              className="p-3 border rounded-xl dark:bg-slate-900 dark:text-white dark:border-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none"
              required
              disabled={words.length >= 10}
            />
            <input
              type="text"
              placeholder="Hint (e.g., Striped horse)"
              value={newHint}
              onChange={(e) => setNewHint(e.target.value)}
              className="p-3 border rounded-xl dark:bg-slate-900 dark:text-white dark:border-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none"
              required
              disabled={words.length >= 10}
            />
            <select
              value={newDifficulty}
              onChange={(e) => setNewDifficulty(e.target.value as Difficulty)}
              className="p-3 border rounded-xl dark:bg-slate-900 dark:text-white dark:border-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none"
              disabled={words.length >= 10}
            >
              <option value={Difficulty.EASY}>Easy</option>
              <option value={Difficulty.MEDIUM}>Medium</option>
              <option value={Difficulty.HARD}>Hard</option>
            </select>
            <Button 
              type="submit" 
              variant="primary" 
              disabled={words.length >= 10}
              className={words.length >= 10 ? 'opacity-50 cursor-not-allowed' : ''}
            >
              Add Word
            </Button>
          </form>
          {words.length >= 10 && (
            <p className="text-red-500 text-sm mt-2 font-medium">
              Maximum word limit reached. Students must complete words or you must delete them to add more.
            </p>
          )}
        </div>

        {/* Word List */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700">
          <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-4">Custom Words Database</h3>
          {words.length === 0 ? (
            <p className="text-slate-500 italic text-center py-8">No custom words added yet.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="text-slate-500 border-b dark:border-slate-600">
                    <th className="pb-2">Word</th>
                    <th className="pb-2">Hint</th>
                    <th className="pb-2">Level</th>
                    <th className="pb-2 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="text-slate-700 dark:text-slate-300">
                  {words.map((w) => (
                    <tr key={w.id} className="border-b last:border-0 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700/50">
                      <td className="py-3 font-bold">{w.word}</td>
                      <td className="py-3">{w.hint}</td>
                      <td className="py-3">
                        <span className={`text-xs font-bold px-2 py-1 rounded-full ${
                          w.difficulty === Difficulty.EASY ? 'bg-green-100 text-green-700' :
                          w.difficulty === Difficulty.MEDIUM ? 'bg-blue-100 text-blue-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {w.difficulty}
                        </span>
                      </td>
                      <td className="py-3 text-right">
                        <button 
                          onClick={() => handleDelete(w.id)}
                          className="text-red-500 hover:text-red-700 font-bold text-sm bg-red-50 dark:bg-red-900/20 px-3 py-1 rounded-lg transition-colors"
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect, useCallback } from 'react';
import { generateWordList, generateCustomGameWords, getCustomWords, deleteCustomWord } from './services/wordService';
import { audioService } from './services/audioService';
import VirtualKeyboard from './components/VirtualKeyboard';
import WordDisplay from './components/WordDisplay';
import Button from './components/Button';
import AdminPanel from './components/AdminPanel';
import SettingsPanel from './components/SettingsPanel';
import { Difficulty, GameState, SpellingWord, CustomWord, AppSettings } from './types';

// Icons
const VolumeIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-8 h-8">
    <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" />
  </svg>
);

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [selectedLetter, setSelectedLetter] = useState<string>('ALL');
  const [wordList, setWordList] = useState<SpellingWord[]>([]);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  const [spelledIndex, setSpelledIndex] = useState(0);
  const [shake, setShake] = useState(false);
  const [loading, setLoading] = useState(false);

  // Custom Game Tracking
  const [isCustomGame, setIsCustomGame] = useState(false);

  // Score State
  const [score, setScore] = useState(0);

  // Settings State
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('spellbound_settings');
    return saved ? JSON.parse(saved) : { theme: 'light', font: 'sans' };
  });

  const currentWordData = wordList[currentWordIndex];
  const targetWord = currentWordData?.word.toUpperCase() || "";

  // Apply Theme & Font
  useEffect(() => {
    // Save settings
    localStorage.setItem('spellbound_settings', JSON.stringify(settings));

    // Apply Dark Mode
    if (settings.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Apply Font
    document.body.className = `bg-sky-100 dark:bg-slate-900 text-slate-800 dark:text-slate-100 transition-colors duration-300 selection:bg-yellow-200 font-${settings.font}`;
  }, [settings]);

  // Use browser native SpeechSynthesis
  const playWordAudio = useCallback((word: string) => {
    if (!word) return;

    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.rate = 0.8;
    utterance.pitch = 1.1;

    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => 
      v.name.includes('Google US English') || 
      (v.lang.startsWith('en') && v.name.includes('Female'))
    ) || voices.find(v => v.lang.startsWith('en'));

    if (preferredVoice) utterance.voice = preferredVoice;
    window.speechSynthesis.speak(utterance);
  }, []);

  const getPointsPerWord = (diff: Difficulty) => {
    switch (diff) {
      case Difficulty.EASY: return 10;
      case Difficulty.MEDIUM: return 20;
      case Difficulty.HARD: return 30;
    }
  };

  const startGame = async () => {
    setGameState(GameState.LOADING);
    setLoading(true);
    setScore(0); // Reset score
    setIsCustomGame(false);

    try {
      const words = await generateWordList(difficulty, selectedLetter);
      setWordList(words);
      setCurrentWordIndex(0);
      setSpelledIndex(0);
      setGameState(GameState.PLAYING);

      if (words.length > 0) {
        setTimeout(() => {
          playWordAudio(words[0].word);
        }, 800);
      }
    } catch (e) {
      console.error("Failed to start game", e);
      setGameState(GameState.MENU);
    } finally {
      setLoading(false);
    }
  };

  const startCustomGame = async () => {
    setGameState(GameState.LOADING);
    setLoading(true);
    setScore(0);
    setIsCustomGame(true);

    try {
      const words = generateCustomGameWords();

      if (words.length === 0) {
        alert("No instructor words found! Ask your teacher to add some.");
        setGameState(GameState.MENU);
        setLoading(false);
        return;
      }

      setWordList(words);
      setCurrentWordIndex(0);
      setSpelledIndex(0);
      setGameState(GameState.PLAYING);

      if (words.length > 0) {
        setTimeout(() => {
          playWordAudio(words[0].word);
        }, 800);
      }
    } catch (e) {
      console.error("Failed to start custom game", e);
      setGameState(GameState.MENU);
    } finally {
      setLoading(false);
    }
  };

  const handleInput = useCallback((char: string) => {
    if (gameState !== GameState.PLAYING) return;

    const correctChar = targetWord[spelledIndex];

    if (char.toUpperCase() === correctChar) {
      // Correct Letter
      audioService.playSuccess();
      const nextIndex = spelledIndex + 1;
      setSpelledIndex(nextIndex);

      if (nextIndex === targetWord.length) {
        // Word Completed
        const points = getPointsPerWord(difficulty);
        setScore(prev => prev + points);

        // Remove from custom list if playing Instructor Challenge
        if (isCustomGame) {
          const customWord = currentWordData as CustomWord;
          if (customWord && customWord.id) {
            deleteCustomWord(customWord.id);
          }
        }

        setTimeout(() => {
          audioService.playVictory();
          handleNextWord();
        }, 500);
      }
    } else {
      // Wrong Letter
      audioService.playError();
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  }, [gameState, targetWord, spelledIndex, difficulty, playWordAudio, isCustomGame, currentWordData]);

  const handleNextWord = () => {
    if (currentWordIndex + 1 < wordList.length) {
      setCurrentWordIndex(prev => prev + 1);
      setSpelledIndex(0);
      setTimeout(() => {
        playWordAudio(wordList[currentWordIndex + 1].word);
      }, 1000);
    } else {
      setGameState(GameState.VICTORY);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const char = e.key.toUpperCase();
      if (/^[A-Z]$/.test(char)) {
        handleInput(char);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleInput]);


  // --- Render Views ---

  if (gameState === GameState.ADMIN) {
    return <AdminPanel onBack={() => setGameState(GameState.MENU)} />;
  }

  if (gameState === GameState.MENU) {
    const hasCustomWords = getCustomWords().length > 0;

    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed">

        <div className="max-w-4xl w-full text-center space-y-6 bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm p-8 md:p-12 rounded-3xl shadow-2xl border-4 border-white dark:border-slate-700 my-8 transition-colors">
          <div className="flex justify-end gap-2 absolute top-6 right-6">
             <button 
              onClick={() => setGameState(GameState.SETTINGS)}
              className="p-2 text-slate-400 hover:text-indigo-500 transition-colors"
              title="Settings"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
            </button>
          </div>

          <h1 className="text-5xl md:text-6xl font-black text-indigo-600 dark:text-indigo-400 tracking-tight animate-float mb-8">
            SpellBound <span className="text-yellow-500">Kids</span>
          </h1>

          <div className="space-y-8">
            {/* Custom Words Section - Only shows if words exist */}
            {hasCustomWords && (
              <div className="bg-indigo-50 dark:bg-indigo-900/20 border-2 border-indigo-200 dark:border-indigo-800 rounded-2xl p-4 animate-pulse">
                <h3 className="text-lg font-bold text-indigo-700 dark:text-indigo-300 uppercase tracking-wider mb-2">
                  🎓 Teacher's Challenge 🎓
                </h3>
                <p className="text-sm text-indigo-600 dark:text-indigo-300 mb-4">
                  Test your skills on words added by your instructor!
                </p>
                <Button onClick={startCustomGame} variant="selected" className="w-full sm:w-auto px-8">
                  Play Instructor Words
                </Button>
              </div>
            )}

            {/* Difficulty Section */}
            <div className="space-y-3">
              <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">1. Select Level</h3>
              <div className="flex flex-wrap gap-4 justify-center">
                <Button 
                  onClick={() => setDifficulty(Difficulty.EASY)} 
                  variant={difficulty === Difficulty.EASY ? 'selected' : 'outline'}
                >
                  Easy 🌟
                </Button>
                <Button 
                  onClick={() => setDifficulty(Difficulty.MEDIUM)} 
                  variant={difficulty === Difficulty.MEDIUM ? 'selected' : 'outline'}
                >
                  Medium 🚀
                </Button>
                <Button 
                  onClick={() => setDifficulty(Difficulty.HARD)} 
                  variant={difficulty === Difficulty.HARD ? 'selected' : 'outline'}
                >
                  Hard 🦁
                </Button>
              </div>
            </div>

            {/* Alphabet Section */}
            <div className="space-y-3">
              <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">2. Select Letter</h3>
              <div className="flex flex-wrap justify-center gap-2 max-w-2xl mx-auto">
                <Button 
                  onClick={() => setSelectedLetter('ALL')}
                  variant={selectedLetter === 'ALL' ? 'selected' : 'outline'}
                  className="w-full sm:w-auto px-8"
                >
                  All Letters
                </Button>
                <div className="w-full"></div>
                {ALPHABET.map(letter => (
                  <Button
                    key={letter}
                    onClick={() => setSelectedLetter(letter)}
                    variant={selectedLetter === letter ? 'selected' : 'outline'}
                    size="xl"
                  >
                    {letter}
                  </Button>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="pt-8 flex flex-col md:flex-row gap-4 justify-center items-center">
              <Button onClick={() => setGameState(GameState.ADMIN)} variant="secondary" className="w-full md:w-auto">
                Instructor Panel 👨‍🏫
              </Button>
              <Button onClick={startGame} variant="primary" size="lg" className="w-full md:w-auto min-w-[200px]">
                START GAME ▶
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (gameState === GameState.SETTINGS) {
    return (
      <SettingsPanel 
        settings={settings} 
        onUpdate={setSettings} 
        onBack={() => setGameState(GameState.MENU)} 
      />
    );
  }

  if (gameState === GameState.LOADING) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center space-y-6 bg-sky-100 dark:bg-slate-900">
        <div className="w-24 h-24 border-8 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
        <h2 className="text-3xl font-bold text-blue-600 animate-pulse">Preparing Words...</h2>
      </div>
    );
  }

  if (gameState === GameState.VICTORY) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 text-center bg-yellow-100 dark:bg-slate-900 transition-colors">
        <h1 className="text-6xl md:text-8xl font-black text-yellow-500 mb-8 drop-shadow-lg animate-bounce">
          CONGRATULATIONS!
        </h1>
        <p className="text-3xl text-slate-700 dark:text-slate-200 mb-8">You are a Spelling Master! 🏆</p>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl mb-12 border-4 border-yellow-200 dark:border-slate-700">
          <p className="text-slate-500 dark:text-slate-400 uppercase tracking-widest font-bold mb-2">Final Score</p>
          <p className="text-6xl font-black text-indigo-600 dark:text-indigo-400">{score}</p>
        </div>

        <Button onClick={() => setGameState(GameState.MENU)} size="lg" variant="secondary">
          Play Again
        </Button>
      </div>
    );
  }

  // PLAYING STATE
  return (
    <div className="min-h-screen flex flex-col max-w-5xl mx-auto p-4">
      {/* Header */}
      <header className="flex justify-between items-center py-4 px-2">
        <button 
          onClick={() => setGameState(GameState.MENU)}
          className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-800 dark:hover:text-white transition-colors"
        >
          ← Quit
        </button>

        {/* Score Display */}
        <div className="flex gap-4">
            <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Score: <span className="text-indigo-600 dark:text-indigo-400">{score}</span>
          </div>
          <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Word {currentWordIndex + 1} / {wordList.length}
          </div>
        </div>
      </header>

      {/* Main Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center -mt-8">

        {/* Helper/Hint Section */}
        <div className="text-center mb-6 space-y-4">
           <button 
            onClick={() => playWordAudio(targetWord)}
            className="inline-flex items-center gap-2 bg-indigo-100 dark:bg-slate-800 hover:bg-indigo-200 dark:hover:bg-slate-700 text-indigo-700 dark:text-indigo-300 px-8 py-4 rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-md border-2 border-transparent dark:border-slate-600"
          >
            <VolumeIcon />
            <span className="text-xl font-bold">Listen Again</span>
          </button>

          <div className="bg-white/60 dark:bg-slate-800/60 px-6 py-2 rounded-xl text-slate-600 dark:text-slate-300 font-medium">
            Hint: {currentWordData?.hint}
          </div>
        </div>

        {/* The Word Grid */}
        <WordDisplay 
          targetWord={targetWord} 
          currentIndex={spelledIndex} 
          isShake={shake}
        />

      </main>

      {/* Keyboard */}
      <footer className="pb-4">
        <VirtualKeyboard 
          onKeyPress={handleInput} 
          disabled={false}
        />
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { generateWordList, generateCustomGameWords, getCustomWords, deleteCustomWord } from './services/wordService';
import { audioService } from './services/audioService';
import VirtualKeyboard from './components/VirtualKeyboard';
import WordDisplay from './components/WordDisplay';
import Button from './components/Button';
import AdminPanel from './components/AdminPanel';
import SettingsPanel from './components/SettingsPanel';
import { Difficulty, GameState, SpellingWord, CustomWord, AppSettings } from './types';

// Icons
const VolumeIcon = ({ className = "w-8 h-8" }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className={className}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" />
  </svg>
);

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [selectedLetter, setSelectedLetter] = useState<string>('ALL');
  const [wordList, setWordList] = useState<SpellingWord[]>([]);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  const [spelledIndex, setSpelledIndex] = useState(0);
  const [shake, setShake] = useState(false);
  const [loading, setLoading] = useState(false);

  // Custom Game Tracking
  const [isCustomGame, setIsCustomGame] = useState(false);

  // Score State
  const [score, setScore] = useState(0);

  // Settings State
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('spellbound_settings');
    return saved ? JSON.parse(saved) : { theme: 'light', font: 'sans' };
  });

  const currentWordData = wordList[currentWordIndex];
  const targetWord = currentWordData?.word.toUpperCase() || "";

  // Apply Theme & Font
  useEffect(() => {
    // Save settings
    localStorage.setItem('spellbound_settings', JSON.stringify(settings));

    // Apply Dark Mode
    if (settings.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Apply Font
    document.body.className = `bg-sky-100 dark:bg-slate-900 text-slate-800 dark:text-slate-100 transition-colors duration-300 selection:bg-yellow-200 font-${settings.font}`;
  }, [settings]);

  // Use browser native SpeechSynthesis
  const playWordAudio = useCallback((word: string) => {
    if (!word) return;

    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.rate = 0.8;
    utterance.pitch = 1.1;

    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => 
      v.name.includes('Google US English') || 
      (v.lang.startsWith('en') && v.name.includes('Female'))
    ) || voices.find(v => v.lang.startsWith('en'));

    if (preferredVoice) utterance.voice = preferredVoice;
    window.speechSynthesis.speak(utterance);
  }, []);

  const getPointsPerWord = (diff: Difficulty) => {
    switch (diff) {
      case Difficulty.EASY: return 10;
      case Difficulty.MEDIUM: return 20;
      case Difficulty.HARD: return 30;
    }
  };

  const startGame = async () => {
    setGameState(GameState.LOADING);
    setLoading(true);
    setScore(0); // Reset score
    setIsCustomGame(false);

    try {
      const words = await generateWordList(difficulty, selectedLetter);
      setWordList(words);
      setCurrentWordIndex(0);
      setSpelledIndex(0);
      setGameState(GameState.PLAYING);

      if (words.length > 0) {
        setTimeout(() => {
          playWordAudio(words[0].word);
        }, 800);
      }
    } catch (e) {
      console.error("Failed to start game", e);
      setGameState(GameState.MENU);
    } finally {
      setLoading(false);
    }
  };

  const startCustomGame = async () => {
    setGameState(GameState.LOADING);
    setLoading(true);
    setScore(0);
    setIsCustomGame(true);

    try {
      const words = generateCustomGameWords();

      if (words.length === 0) {
        alert("No instructor words found! Ask your teacher to add some.");
        setGameState(GameState.MENU);
        setLoading(false);
        return;
      }

      setWordList(words);
      setCurrentWordIndex(0);
      setSpelledIndex(0);
      setGameState(GameState.PLAYING);

      if (words.length > 0) {
        setTimeout(() => {
          playWordAudio(words[0].word);
        }, 800);
      }
    } catch (e) {
      console.error("Failed to start custom game", e);
      setGameState(GameState.MENU);
    } finally {
      setLoading(false);
    }
  };

  const handleInput = useCallback((char: string) => {
    if (gameState !== GameState.PLAYING) return;

    const correctChar = targetWord[spelledIndex];

    if (char.toUpperCase() === correctChar) {
      // Correct Letter
      audioService.playSuccess();
      const nextIndex = spelledIndex + 1;
      setSpelledIndex(nextIndex);

      if (nextIndex === targetWord.length) {
        // Word Completed
        const points = getPointsPerWord(difficulty);
        setScore(prev => prev + points);

        // Remove from custom list if playing Instructor Challenge
        if (isCustomGame) {
          const customWord = currentWordData as CustomWord;
          if (customWord && customWord.id) {
            deleteCustomWord(customWord.id);
          }
        }

        setTimeout(() => {
          audioService.playVictory();
          handleNextWord();
        }, 500);
      }
    } else {
      // Wrong Letter
      audioService.playError();
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  }, [gameState, targetWord, spelledIndex, difficulty, playWordAudio, isCustomGame, currentWordData]);

  const handleNextWord = () => {
    if (currentWordIndex + 1 < wordList.length) {
      setCurrentWordIndex(prev => prev + 1);
      setSpelledIndex(0);
      setTimeout(() => {
        playWordAudio(wordList[currentWordIndex + 1].word);
      }, 1000);
    } else {
      setGameState(GameState.VICTORY);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const char = e.key.toUpperCase();
      if (/^[A-Z]$/.test(char)) {
        handleInput(char);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleInput]);


  // --- Render Views ---

  if (gameState === GameState.ADMIN) {
    return <AdminPanel onBack={() => setGameState(GameState.MENU)} />;
  }

  if (gameState === GameState.MENU) {
    const hasCustomWords = getCustomWords().length > 0;

    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed">

        <div className="max-w-4xl w-full text-center space-y-6 bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm p-8 md:p-12 rounded-3xl shadow-2xl border-4 border-white dark:border-slate-700 my-8 transition-colors">
          <div className="flex justify-end gap-2 absolute top-6 right-6">
             <button 
              onClick={() => setGameState(GameState.SETTINGS)}
              className="p-2 text-slate-400 hover:text-indigo-500 transition-colors"
              title="Settings"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
            </button>
          </div>

          <h1 className="text-5xl md:text-6xl font-black text-indigo-600 dark:text-indigo-400 tracking-tight animate-float mb-8">
            SpellBound <span className="text-yellow-500">Kids</span>
          </h1>

          <div className="space-y-8">
            {/* Custom Words Section - Only shows if words exist */}
            {hasCustomWords && (
              <div className="bg-indigo-50 dark:bg-indigo-900/20 border-2 border-indigo-200 dark:border-indigo-800 rounded-2xl p-4 animate-pulse">
                <h3 className="text-lg font-bold text-indigo-700 dark:text-indigo-300 uppercase tracking-wider mb-2">
                  🎓 Teacher's Challenge 🎓
                </h3>
                <p className="text-sm text-indigo-600 dark:text-indigo-300 mb-4">
                  Test your skills on words added by your instructor!
                </p>
                <Button onClick={startCustomGame} variant="selected" className="w-full sm:w-auto px-8">
                  Play Instructor Words
                </Button>
              </div>
            )}

            {/* Difficulty Section */}
            <div className="space-y-3">
              <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">1. Select Level</h3>
              <div className="flex flex-wrap gap-4 justify-center">
                <Button 
                  onClick={() => setDifficulty(Difficulty.EASY)} 
                  variant={difficulty === Difficulty.EASY ? 'selected' : 'outline'}
                >
                  Easy 🌟
                </Button>
                <Button 
                  onClick={() => setDifficulty(Difficulty.MEDIUM)} 
                  variant={difficulty === Difficulty.MEDIUM ? 'selected' : 'outline'}
                >
                  Medium 🚀
                </Button>
                <Button 
                  onClick={() => setDifficulty(Difficulty.HARD)} 
                  variant={difficulty === Difficulty.HARD ? 'selected' : 'outline'}
                >
                  Hard 🦁
                </Button>
              </div>
            </div>

            {/* Alphabet Section */}
            <div className="space-y-3">
              <h3 className="text-lg font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">2. Select Letter</h3>
              <div className="flex flex-wrap justify-center gap-2 max-w-2xl mx-auto">
                <Button 
                  onClick={() => setSelectedLetter('ALL')}
                  variant={selectedLetter === 'ALL' ? 'selected' : 'outline'}
                  className="w-full sm:w-auto px-8"
                >
                  All Letters
                </Button>
                <div className="w-full"></div>
                {ALPHABET.map(letter => (
                  <Button
                    key={letter}
                    onClick={() => setSelectedLetter(letter)}
                    variant={selectedLetter === letter ? 'selected' : 'outline'}
                    size="xl"
                  >
                    {letter}
                  </Button>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="pt-8 flex flex-col md:flex-row gap-4 justify-center items-center">
              <Button onClick={() => setGameState(GameState.ADMIN)} variant="secondary" className="w-full md:w-auto">
                Instructor Panel 👨‍🏫
              </Button>
              <Button onClick={startGame} variant="primary" size="lg" className="w-full md:w-auto min-w-[200px]">
                START GAME ▶
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (gameState === GameState.SETTINGS) {
    return (
      <SettingsPanel 
        settings={settings} 
        onUpdate={setSettings} 
        onBack={() => setGameState(GameState.MENU)} 
      />
    );
  }

  if (gameState === GameState.LOADING) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center space-y-6 bg-sky-100 dark:bg-slate-900">
        <div className="w-24 h-24 border-8 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
        <h2 className="text-3xl font-bold text-blue-600 animate-pulse">Preparing Words...</h2>
      </div>
    );
  }

  if (gameState === GameState.VICTORY) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 text-center bg-yellow-100 dark:bg-slate-900 transition-colors">
        <h1 className="text-6xl md:text-8xl font-black text-yellow-500 mb-8 drop-shadow-lg animate-bounce">
          CONGRATULATIONS!
        </h1>
        <p className="text-3xl text-slate-700 dark:text-slate-200 mb-8">You are a Spelling Master! 🏆</p>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl mb-12 border-4 border-yellow-200 dark:border-slate-700">
          <p className="text-slate-500 dark:text-slate-400 uppercase tracking-widest font-bold mb-2">Final Score</p>
          <p className="text-6xl font-black text-indigo-600 dark:text-indigo-400">{score}</p>
        </div>

        <Button onClick={() => setGameState(GameState.MENU)} size="lg" variant="secondary">
          Play Again
        </Button>
      </div>
    );
  }

  // PLAYING STATE
  return (
    <div className="min-h-screen flex flex-col max-w-5xl mx-auto p-4">
      {/* Header */}
      <header className="flex justify-between items-center py-4 px-2">
        <button 
          onClick={() => setGameState(GameState.MENU)}
          className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-800 dark:hover:text-white transition-colors"
        >
          ← Quit
        </button>

        {/* Score Display */}
        <div className="flex flex-col items-end gap-2">
            <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Score: <span className="text-indigo-600 dark:text-indigo-400">{score}</span>
          </div>
          <div className="text-xl font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 px-6 py-2 rounded-full shadow-sm border dark:border-slate-700">
            Word {currentWordIndex + 1} / {wordList.length}
          </div>
        </div>
      </header>

      {/* Main Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center -mt-8">

        {/* Helper/Hint Section */}
        <div className="flex flex-col items-center gap-4 mb-6">
          <div className="flex items-center gap-3 bg-white/60 dark:bg-slate-800/60 px-6 py-3 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 transition-all">
            <span className="text-slate-600 dark:text-slate-300 font-medium text-lg">
              Hint: {currentWordData?.hint}
            </span>
            <button 
              onClick={() => playWordAudio(targetWord)}
              className="p-2 bg-indigo-100 dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 rounded-full hover:bg-indigo-200 dark:hover:bg-slate-600 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-400"
              aria-label="Listen again"
              title="Listen again"
            >
              <VolumeIcon className="w-6 h-6" /> 
            </button>
          </div>
        </div>

        {/* The Word Grid */}
        <WordDisplay 
          targetWord={targetWord} 
          currentIndex={spelledIndex} 
          isShake={shake}
        />

      </main>

      {/* Keyboard */}
      <footer className="pb-4">
        <VirtualKeyboard 
          onKeyPress={handleInput} 
          disabled={false}
        />
      </footer>
    </div>
  );
};

