          </div>

          {/* Font Selection */}
          <div className="space-y-2">
            <h3 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Lettering Style</h3>
            <div className="grid grid-cols-2 gap-2">
              {['sans', 'serif', 'mono', 'comic'].map((f) => (
                 <button
                 key={f}
                 onClick={() => updateFont(f as FontFamily)}
                 className={`p-2 rounded-xl border-2 capitalize transition-all text-sm font-bold font-${f} ${
                   settings.font === f 
                    ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300' 
                    : 'border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-400'
                 }`}
               >
                 {f === 'comic' ? 'Fun' : f}
               </button>
              ))}
            </div>
          </div>

          {/* Information & Legal */}
          <div className="space-y-2 pt-2 border-t border-slate-200 dark:border-slate-700">
             <h3 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">About & Legal</h3>
             <div className="flex flex-col gap-2">
                <button onClick={() => setActiveModal('ABOUT')} className="text-left px-4 py-2 rounded-lg bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-600 font-medium text-sm flex justify-between items-center">
                  <span>ℹ️ About SpellBound Kids</span>
                  <span>→</span>
                </button>
                <button onClick={() => window.open('https://spell-safely-kids.lovable.app', '_blank')} className="text-left px-4 py-2 rounded-lg bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-600 font-medium text-sm flex justify-between items-center">
                  <span>🔒 Privacy Policy</span>
                  <span>→</span>
                </button>
                <button onClick={() => setActiveModal('TERMS')} className="text-left px-4 py-2 rounded-lg bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-600 font-medium text-sm flex justify-between items-center">
